cm={'A':'T','T':'A','C':'G','G':'C'}
def rc(s): return "".join(cm[c] for c in s[::-1])

# TSD scan: for each d, for each L, max k such that seq[L-k:L]==seq[L+d:L+d+k]
best={}
for d in range(200,2801):
    for L in range(1,n-d):
        # cap R = L+d <= n
        if L+d>n: break
        k=1
        while L-k>=0 and L+d+k<=n and seq[L-k]==seq[L+d+k] and k<20:
            k+=1
        k-=1
        if k>=5:
            best.setdefault(d,[]).append((k,L,L+d))
cnt=0
for d in sorted(best):
    for (k,L,R) in best[d]:
        cnt+=1
print("number of (L,R) pairs with TSD>=5:",cnt)
for d in sorted(best):
    for (k,L,R) in sorted(best[d], reverse=True)[:5]:
        print("  d=%d TSD=%d bp  leftcopy %d-%d, rightcopy %d-%d  %s"%(d,k,L-k+1,L,R+1,R+k,seq[L-k+1:L+1]))
"}

